const fs = require('fs');

// Флаг из Set
const useArjun = $input.first().json.useArjun === true;
console.log(`useArjun: ${useArjun}`);

// Самый свежий endpoints.json
const epFiles = fs.readdirSync('/results')
  .filter(f => f.endsWith('_endpoints.json'))
  .map(f => ({ name: f, mtime: fs.statSync(`/results/${f}`).mtime.getTime() }))
  .sort((a, b) => b.mtime - a.mtime);

if (epFiles.length === 0) throw new Error('No endpoints.json found');

const discovery = JSON.parse(fs.readFileSync(`/results/${epFiles[0].name}`, 'utf8'));
console.log(`Loaded: ${discovery.runId} (${discovery.endpointCount} endpoints)`);

// Arjun только если useArjun=true
let arjunParams = {};
let arjunStatus = 'disabled';

if (useArjun && discovery.arjunFile && fs.existsSync(discovery.arjunFile)) {
  try {
    const arjun = JSON.parse(fs.readFileSync(discovery.arjunFile, 'utf8'));
    if (arjun.arjunSkipped) {
      arjunStatus = 'skipped';
    } else {
      arjunParams = arjun.arjunParams || {};
      arjunStatus = 'loaded';
      const n = Object.keys(arjunParams).length;
      const total = Object.values(arjunParams).flat().length;
      console.log(`Arjun loaded: ${n} endpoints, ${total} params`);
    }
  } catch (e) {
    arjunStatus = 'parse-error';
    console.warn('Arjun read error:', e.message);
  }
} else if (useArjun) {
  arjunStatus = 'file-missing';
  console.log('Arjun file missing — using DEFAULT_PARAMS');
} else {
  console.log('useArjun=false — using DEFAULT_PARAMS');
}

return [{ json: {
  ...discovery,
  useArjun,
  arjunStatus,
  arjunParams,
}}];

const cfg = $input.first().json;

const endpoints = (cfg.endpoints || [])
  .filter(ep => !/\.(js|css|png|jpg|jpeg|svg|woff2?|ttf|ico|map)$/i.test(ep))
  .filter((v, i, a) => a.indexOf(v) === i);

if (endpoints.length === 0) endpoints.push(cfg.target);

const DEFAULT_PARAMS = ['id', 'q', 'search', 'query', 'file', 'url', 'name'];
const arjunParams = cfg.arjunParams || {};

const allParams = {};
let arjunCovered = 0;

for (const ep of endpoints) {
  const discovered = arjunParams[ep] || [];
  if (discovered.length > 0) {
    allParams[ep] = discovered;
    arjunCovered++;
    console.log(`Arjun params for ${ep}: ${discovered.join(', ')}`);
  } else {
    allParams[ep] = DEFAULT_PARAMS;
  }
}

console.log(`Expand: ${endpoints.length} endpoints, arjun-covered: ${arjunCovered}`);

return [{ json: {
  ...cfg,
  allParams,
  endpointCount: endpoints.length,
}}];

const fs = require('fs');
const cfg = $input.first().json;
const allParams = cfg.allParams || {};
const paramTypes = cfg.openApiParamTypes || {};
const puppeteerParams = cfg.puppeteerForms || [];

for (const [endpoint, params] of Object.entries(allParams)) {
  allParams[endpoint] = [...new Set([...params, ...puppeteerParams])];
}

const OWASP_ENDPOINT_FILTER = {
  A01_Broken_Access_Control:     /(api\/users|login|admin|user)/i,
  A03_Injection_SQLi:            /(sqli|login|user|search|api)/i,
  A03_Injection_XSS:             /(xss|search|reflected|stored|dom|contact)/i,
  A03_Injection_SSTI:            /(ssti|template|page)/i,
  A03_Injection_CMD:             /(rce|ping|eval)/i,
  A03_Injection_LFI:             /(ptrav|read|download|file|page)/i,
  A05_Security_Misconfiguration: /./,
  A07_Auth_Failures:             /(login|auth|token|session)/i,
  A10_SSRF:                      /(redirect|redir|url|fetch|proxy|webhook)/i,
};

const filter = OWASP_ENDPOINT_FILTER[cfg.vulnType] || /./;
const DEFAULT_PARAMS = ['id', 'q', 'search', 'query', 'file', 'url', 'name'];

// Загружаем базовый словарь (SecLists) в память
let basePayloads = [];
try {
  basePayloads = fs.readFileSync(cfg.wordlist, 'utf8').split('\n').filter(l => l.trim());
} catch (e) {
  console.error('Wordlist read error:', e.message);
  basePayloads = ['FUZZ']; // fallback
}

const jobs = [];
let i = 0;
const MAX_JOBS = 30;

for (const [endpoint, params] of Object.entries(allParams)) {
  if (!filter.test(endpoint)) continue;

  const paramsToUse = (params && params.length > 0) ? params : DEFAULT_PARAMS;
  const epTypes = paramTypes[endpoint] || {};

  for (const param of paramsToUse) {
    if (i >= MAX_JOBS) break;

    let currentWordlist = cfg.wordlist;
    const pType = epTypes[param]?.type;
    const pFormat = epTypes[param]?.format;

    // === УМНАЯ МУТАЦИЯ (Smart Fuzzing) ===
    if (pFormat === 'uuid' || pFormat === 'email' || pType === 'integer') {
      const customWordlistPath = `/results/${cfg.runId}_custom_${i}.txt`;
      const mutatedPayloads = basePayloads.map(payload => {
        if (pFormat === 'email') return `admin"${payload}"@test.com`;
        if (pFormat === 'uuid') return `123e4567-e89b-12d3-a456-${payload.substring(0,12).padEnd(12, '0')}`;
        if (pType === 'integer') return `${Math.floor(Math.random() * 100)}${payload}`;
        return payload;
      });
      fs.writeFileSync(customWordlistPath, mutatedPayloads.join('\n'));
      currentWordlist = customWordlistPath;
    }

    jobs.push({
      endpoint, param,
      target: cfg.target,
      wordlist: currentWordlist, // Используем базовый или мутированный
      vulnType: cfg.vulnType,
      owaspCategory: cfg.owaspCategory,
      owaspName: cfg.owaspName,
      runId: cfg.runId,
      ffufOut:  `/results/${cfg.runId}_ffuf_${i}.json`,
      wfuzzOut: `/results/${cfg.runId}_wfuzz_${i}.txt`,
      // Пробрасываем пути для следующих узлов
      dictResultsFile: cfg.dictResultsFile,
      schemaResultsFile: cfg.schemaResultsFile,
      reportFile: cfg.reportFile
    });
    i++;
  }
  if (i >= MAX_JOBS) break;
}

return jobs.map(j => ({ json: j }));

const fs = require('fs');
const path = require('path');

await new Promise(r => setTimeout(r, 2000));

// ⚠️ Берём cfg из Build jobs (там есть runId и пути)
const jobs = $('Build jobs').all().map(item => item.json);
const runId = jobs[0]?.runId || '';

const normalized = [];

const files = fs.readdirSync('/results').filter(f =>
  f.startsWith(runId) && f.includes('_ffuf_') && f.endsWith('.json')
);

console.log(`Parse ffuf: ${files.length} files, ${jobs.length} jobs`);

for (const file of files) {
  try {
    const data = JSON.parse(fs.readFileSync(path.join('/results', file), 'utf8'));
    const results = data.results || [];

    const m = file.match(/_ffuf_(\d+)\.json$/);
    const idx = m ? parseInt(m[1]) : -1;
    const job = (idx >= 0 && idx < jobs.length) ? jobs[idx] : null;

    const endpoint = job ? job.endpoint : 'unknown';
    const param = job ? job.param : `param_${idx}`;

    for (const r of results) {
      normalized.push({
        tool: 'ffuf',
        endpoint,
        param,
        payload: (r.input && r.input.FUZZ) || '',
        status: r.status,
        length: r.length,
        time_ms: Math.round((r.duration || 0) / 1_000_000),
        contentType: r['content-type'] || '',
      });
    }
  } catch (e) {
    console.error('Parse ffuf error:', file, e.message);
  }
}

console.log(`Parsed ffuf: ${normalized.length} results`);
return [{ json: { tool: 'ffuf', normalized }}];

const fs = require('fs');
const path = require('path');

await new Promise(r => setTimeout(r, 2000));

const jobs = $('Build jobs').all().map(item => item.json);
const runId = jobs[0]?.runId || '';

const normalized = [];

const files = fs.readdirSync('/results').filter(f =>
  f.startsWith(runId) && f.includes('_wfuzz_') && f.endsWith('.txt')
);

console.log(`Parse wfuzz: ${files.length} files, ${jobs.length} jobs`);

for (const file of files) {
  try {
    const text = fs.readFileSync(path.join('/results', file), 'utf8');
    const lines = text.split('\n');

    const m = file.match(/_wfuzz_(\d+)\.txt$/);
    const idx = m ? parseInt(m[1]) : -1;
    const job = (idx >= 0 && idx < jobs.length) ? jobs[idx] : null;

    const endpoint = job ? job.endpoint : 'unknown';
    const param = job ? job.param : `param_${idx}`;

    for (const line of lines) {
      const match = line.match(/^\s*\d+:\s+C=(\d+)\s+(\d+)\s+L\s+(\d+)\s+W\s+(\d+)\s+Ch\s+"(.*)"/);
      if (!match) continue;

      normalized.push({
        tool: 'wfuzz',
        endpoint,
        param,
        payload: (match[5] || '').trim(),
        status:  parseInt(match[1]),
        length:  parseInt(match[4]),
        words:   parseInt(match[3]),
        chars:   parseInt(match[4]),
        time_ms: 0,
        contentType: '',
      });
    }
  } catch (e) {
    console.error('Parse wfuzz error:', file, e.message);
  }
}

console.log(`Parsed wfuzz: ${normalized.length} results`);
return [{ json: { tool: 'wfuzz', normalized }}];

const fs = require('fs');
const data = $input.first().json;

const dictResults = {
  runId: data.runId,
  target: data.target,
  vulnType: data.vulnType,
  wordlist: data.wordlist,
  useArjun: data.useArjun || false,
  arjunStatus: data.arjunStatus || 'unknown',

  ffuf:  { results: data.ffufResults  || [], total: (data.ffufResults  || []).length },
  wfuzz: { results: data.wfuzzResults || [], total: (data.wfuzzResults || []).length },

  totalResults: (data.ffufResults?.length || 0) + (data.wfuzzResults?.length || 0),
  timestamp: new Date().toISOString(),

  endpointsFile:     data.endpointsFile,
  arjunFile:         data.arjunFile,
  dictResultsFile:   data.dictResultsFile,
  schemaResultsFile: data.schemaResultsFile,
  reportFile:        data.reportFile,
  configFile:        data.configFile,
  baselineFile:      data.baselineFile,

  // ← здесь было cfg. — исправляем на data.
  owaspCategory: data.owaspCategory,
  owaspName: data.owaspName,
  startTime: data.startTime,
};

fs.writeFileSync(data.dictResultsFile, JSON.stringify(dictResults, null, 2));

console.log(`Workflow 3 DONE. ffuf=${dictResults.ffuf.total}, wfuzz=${dictResults.wfuzz.total}, total=${dictResults.totalResults}`);
console.log(`File: ${data.dictResultsFile}`);

return [{ json: dictResults }];

const fs = require('fs');
const path = require('path');

await new Promise(r => setTimeout(r, 2000));

// cfg — из Build jobs, там runId и все пути
const jobs = $('Build jobs').all().map(i => i.json);
const runId = jobs[0]?.runId || '';
const cfg = $('Read Files').first().json;

const ffufNorm = [];
const wfuzzNorm = [];

// === Читаем ffuf-файлы ===
const ffufFiles = fs.readdirSync('/results').filter(f =>
  f.startsWith(runId) && f.includes('_ffuf_') && f.endsWith('.json')
);

for (const file of ffufFiles) {
  try {
    const data = JSON.parse(fs.readFileSync(path.join('/results', file), 'utf8'));
    const results = data.results || [];
    const m = file.match(/_ffuf_(\d+)\.json$/);
    const idx = m ? parseInt(m[1]) : -1;
    const job = (idx >= 0 && idx < jobs.length) ? jobs[idx] : null;

    for (const r of results) {
      ffufNorm.push({
        tool: 'ffuf',
        endpoint: job?.endpoint || 'unknown',
        param:    job?.param    || `param_${idx}`,
        payload:  (r.input && r.input.FUZZ) || '',
        status:   r.status,
        length:   r.length,
        time_ms:  Math.round((r.duration || 0) / 1_000_000),
        contentType: r['content-type'] || '',
      });
    }
  } catch (e) {
    console.error('ffuf parse error:', file, e.message);
  }
}

// === Читаем wfuzz-файлы ===
const wfuzzFiles = fs.readdirSync('/results').filter(f =>
  f.startsWith(runId) && f.includes('_wfuzz_') && f.endsWith('.txt')
);

for (const file of wfuzzFiles) {
  try {
    const text = fs.readFileSync(path.join('/results', file), 'utf8');
    const m = file.match(/_wfuzz_(\d+)\.txt$/);
    const idx = m ? parseInt(m[1]) : -1;
    const job = (idx >= 0 && idx < jobs.length) ? jobs[idx] : null;

    for (const line of text.split('\n')) {
      const match = line.match(/^\s*\d+:\s+C=(\d+)\s+(\d+)\s+L\s+(\d+)\s+W\s+(\d+)\s+Ch\s+"(.*)"/);
      if (!match) continue;
      wfuzzNorm.push({
        tool: 'wfuzz',
        endpoint: job?.endpoint || 'unknown',
        param:    job?.param    || `param_${idx}`,
        payload:  (match[5] || '').trim(),
        status:   parseInt(match[1]),
        length:   parseInt(match[4]),
        words:    parseInt(match[3]),
        chars:    parseInt(match[4]),
        time_ms:  0,
        contentType: '',
      });
    }
  } catch (e) {
    console.error('wfuzz parse error:', file, e.message);
  }
}

console.log(`Parsed: ffuf=${ffufNorm.length}, wfuzz=${wfuzzNorm.length}`);

return [{ json: {
  ...cfg,
  ffufResults:  ffufNorm,
  wfuzzResults: wfuzzNorm,
}}];

