const fs = require('fs');
const cfg = $('Read Files').first().json;

const runId = cfg.runId || 'default_run';
const fileName = `/seeds/ai_wordlist_${runId}.txt`;

try {
  let llmRaw = $input.first().json.response || "";

  // 1. Убираем маркдаун-теги (```sql и ```)
  llmRaw = llmRaw.replace(/```[a-z]*/gi, '').replace(/```/g, '').trim();

  // 2. Разбиваем на строки
  let lines = llmRaw.split('\n');

  // 3. Очищаем каждую строку
  let words = lines.map(line => line.trim().replace(/^["']|["']$/g, ''))
    .filter(word => {
      if (!word || word.length < 2) return false;
      if (word.toLowerCase().includes('empty')) return false;
      return true;
    });

  // 4. Если строк меньше 3 — откат на SecLists
  if (words.length < 3) {
    throw new Error(`Модель выдала слишком мало строк (${words.length}).`);
  }

  // 5. Сохраняем
  fs.writeFileSync(fileName, words.join('\n'));

  console.log(`✅ Успешно сохранено ${words.length} строк.`);
  console.log(`Пример: ${words[0]} | ${words[1]}`);

  return [{ json: { 
    ...cfg, 
    wordlist: fileName, 
    aiGenerated: true, 
    aiWordsCount: words.length 
  }}];

} catch (error) {
  console.error("❌ Ошибка LLM, откат на SecLists:", error.message);
  return [{ json: { ...cfg, wordlist: cfg.wordlist, aiGenerated: false } }];
}

const history = $input.all();
const cfg = $('Read Files').first().json;

let summary = "";
if (history.length === 0) {
  summary = "Это первый запуск для данной цели. Используй стандартные параметры.";
} else {
  summary = history.map((item, index) => {
    const d = item.json;
    // Смотрим, сколько было ошибок 500 (сервер падал)
    const errors500 = d.statusBreakdown?.["500"] || 0;
    const time = d.metrics?.totalDurationSec || 0;
    return `Запуск ${index + 1}: ошибок 500=${errors500}, время=${time}с.`;
  }).join(" ");
}
console.log(`📊 История: ${summary}`);
return [{ json: { ...cfg, historySummary: summary } }];

