const cfg = $('Read Files').first().json;
try {
  const parsed = JSON.parse($input.first().json.response);
  let threads = parseInt(parsed.ffuf_threads) || 50;
  let delay = parseInt(parsed.ffuf_delay) || 0;

  // Защита от галлюцинаций ИИ
  if (threads < 10) threads = 10;
  if (threads > 150) threads = 150;
  if (delay < 0) delay = 0;

  console.log(`🤖 ИИ предложил: threads=${threads}, delay=${delay}`);

  return [{ json: { ...cfg, aiThreads: threads, aiDelay: delay } }];
} catch (e) {
  console.error("Ошибка парсинга, ставим дефолт 50");
  return [{ json: { ...cfg, aiThreads: 50, aiDelay: 0 } }];
}
